tool_input.command:
$env:PYTHONIOENCODING='utf-8'
Write-Output "== 复查：仍存在'深市7条/深市专用标准/沪市19深市26'等过时表述的文档 =="
foreach($f in (Get-ChildItem '分析产出' -Filter '*.md').Name){
  $hits=Select-String -Path "分析产出\$f" -Pattern '深市 7 条|深市专用标准（7|沪 19 只 / 深 26|沪市 11 条 / 深市 7 条' 
  if($hits){ foreach($h in $hits){ "$f : $($h.LineNumber): $($h.Line.Trim().Substring(0,[Math]::Min(60,$h.Line.Trim().Length)))" } }
}
Write-Output "（无输出=已清理干净）"

$env:PYTHONIOENCODING='utf-8'
Write-Output "== 筛选标准_最终版 全部深市结论相关位置复核 =="
Select-String -Path '分析产出\筛选标准_最终版.md' -Pattern '深市 3 只|深市三只|深市无一通过|深市子池.*补 3|格力.*兴蓉|3 只' | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(55,$_.Line.Trim().Length)))"}
